SELECT ac.id, ac.approve_status AS approveStatus, ac.approve_user_id AS approveUserId, ac.approve_user_name AS approveUserName, ac.approve_time AS approveTime, ac.invalid_status AS invalidStatus, ac.invalid_remark AS invalidRemark, ac.invalid_time AS invalidTime, ac.source_code AS sourceCode, ac.source_type AS sourceType, ac.source_id AS sourceId, ac.org_id AS orgId, ac.org_name AS orgName, ac.type, ac.code, ac.status, ac.change_method AS changeMethod, ac.name, ac.unit, ac.qty, ac.start_use_date AS startUseDate, ac.asset_code AS assetCode, ac.asset_location_id AS assetLocationId, ac.disposal_status AS disposalStatus, ac.remark, ac.create_time AS createTime, ac.create_user_name AS createUserName, -- 明细表字段（不包含通用字段） acd.id AS detailId, acd.source_detail_id AS sourceDetailId, acd.asset_code AS detailAssetCode, acd.asset_location_id AS detailAssetLocationId, acd.qty AS detailQty, acd.supplier_id AS supplierId, acd.supplier_name AS supplierName, acd.use_dept_name AS useDeptName, acd.use_dept_id AS useDeptId, acd.cost_type AS costType, acd.remark AS detailRemark FROM asset_card ac LEFT JOIN asset_card_detail acd ON acd.main_id = ac.id AND acd.is_deleted = false WHERE ${params.sqlMap.default} AND ac.is_deleted = false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ac.create_time DESC

SELECT ac.id, ac.approve_status AS approveStatus, ac.approve_user_id AS approveUserId, ac.approve_user_name AS approveUserName, ac.approve_time AS approveTime, ac.invalid_status AS invalidStatus, ac.invalid_remark AS invalidRemark, ac.invalid_time AS invalidTime, ac.source_code AS sourceCode, ac.source_type AS sourceType, ac.source_id AS sourceId, ac.org_id AS orgId, ac.org_name AS orgName, ac.type, ac.code, ac.status, ac.change_method AS changeMethod, ac.name, ac.unit, ac.qty, ac.start_use_date AS startUseDate, ac.asset_code AS assetCode, ac.asset_location_id AS assetLocationId, ac.disposal_status AS disposalStatus, ac.remark, ac.create_time AS createTime, ac.create_user_name AS createUserName, -- 明细表字段（不包含通用字段） acd.id AS detailId, acd.source_detail_id AS sourceDetailId, acd.asset_code AS detailAssetCode, acd.asset_location_id AS detailAssetLocationId, acd.qty AS detailQty, acd.supplier_id AS supplierId, acd.supplier_name AS supplierName, acd.use_dept_name AS useDeptName, acd.use_dept_id AS useDeptId, acd.cost_type AS costType, acd.remark AS detailRemark FROM asset_card ac LEFT JOIN asset_card_detail acd ON acd.main_id = ac.id AND acd.is_deleted = false WHERE ${params.sqlMap.default} AND ac.is_deleted = false
AND ac.id IN
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
ac.create_time DESC

SELECT approve_status AS tabFlag, count(*) AS count FROM asset_card WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
